insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_pe1_v1'
from (values
('116.62.c.1.A',3,'A lifter adds a little more weight to the bar each week so the muscles keep adapting. Which training principle is this?','["Progressive overload", "Rest and recovery", "Reversibility", "Specificity"]'::jsonb,0,'Gradually raising the load is progressive overload.','original'),
('116.62.c.1.A',3,'A swimmer trains only in the pool and finds that her running endurance barely improves. Which principle explains this?','["Variety", "Specificity: the body adapts to the type of training done", "Overload", "Individuality"]'::jsonb,1,'Training effects are specific to the activity.','original'),
('116.62.c.1.B',3,'Using a longer lever, such as a straight arm, makes a throw travel faster at the hand. What biomechanical idea is this?','["Gravity stops throwing", "Friction speeds the ball", "Longer levers can produce greater speed at the end", "Balance is not needed"]'::jsonb,2,'A longer lever moves its tip faster for the same rotation.','original'),
('116.62.c.1.B',3,'A sprinter pushes backward against the track and moves forward. Which law of motion describes this?','["The law of gravity only", "Newton''s first law only", "The law of friction only", "Newton''s third law: every action has an equal and opposite reaction"]'::jsonb,3,'Pushing back on the ground drives the body forward.','original'),
('116.62.c.2.A',2,'Before a workout on a weight machine, which safety step should you take first?','["Check that the pin and seat are set correctly", "Skip the warm-up", "Add the heaviest weight", "Ignore the instructions"]'::jsonb,0,'Checking equipment prevents injuries.','original'),
('116.62.c.2.A',2,'Why should a spotter be used on a heavy bench press?','["To make the lift harder", "To help if the lifter cannot finish a repetition", "To block other lifters", "To count the weight plates"]'::jsonb,1,'A spotter keeps the lifter safe.','original'),
('116.62.c.2.B',3,'A student practices a jump rope skill ten minutes a day for two weeks and gets smoother. This shows that skills improve with what?','["Avoiding practice", "Skipping warm-ups", "Regular, focused practice", "Luck alone"]'::jsonb,2,'Deliberate practice improves performance.','original'),
('116.62.c.2.B',3,'Which practice habit best improves a skill during fitness activities?','["Rushing through each rep", "Changing the skill every minute", "Practicing only when tired", "Repeating the movement with correct form and getting feedback"]'::jsonb,3,'Correct repetition builds skill.','original'),
('116.62.c.2.C',2,'A student performs a basic squat with feet shoulder-width apart and knees tracking over the toes. This shows competency in what?','["Using the proper technique for a basic exercise", "Rock climbing", "Marathon pacing", "Advanced Olympic lifting"]'::jsonb,0,'Basic competency means correct form on a basic skill.','original'),
('116.62.c.2.C',3,'A competent performer of a basic push-up keeps the body in what position?','["Hips high in the air", "A straight line from head to heels", "Head dropped with a rounded back", "Hips sagging to the floor"]'::jsonb,1,'A straight body line shows correct form.','original'),
('116.62.c.2.D',3,'A coach tells a student to keep her elbows closer to her body during a row. Using the coach''s comment to adjust is which type of feedback?','["No feedback", "Random feedback", "External feedback", "Internal feedback only"]'::jsonb,2,'Feedback from another person is external.','original'),
('116.62.c.2.D',3,'You feel your lower back arching on an overhead press and fix your posture. This is an example of what?','["Copying a stranger", "Ignoring feedback", "Relying only on a coach", "Using internal feedback from body sensations"]'::jsonb,3,'Body sensations provide internal feedback.','original'),
('116.62.c.2.E',3,'A workout alternates 30 seconds of hard effort with 30 seconds of rest for several rounds. What method is this?','["Interval training", "Continuous easy walking", "A cool-down", "Static stretching"]'::jsonb,0,'Alternating work and rest periods is interval training.','original'),
('116.62.c.2.E',3,'A routine moves through six stations of different exercises with little rest between them. What method is this?','["A warm-up walk", "Circuit training", "Single-set training", "A flexibility test"]'::jsonb,1,'Circuit training rotates through stations.','original'),
('116.62.c.3.A',2,'Which clothing choice is best for a safe workout?','["Sandals", "Dress shoes", "Supportive athletic shoes and clothing that allows free movement", "Jeans that restrict motion"]'::jsonb,2,'Proper attire reduces injury risk.','original'),
('116.62.c.3.A',2,'Before using free weights, a student should do what with the equipment?','["Leave it on the floor", "Throw it to a partner", "Overload it right away", "Inspect it and use collars and proper lifting technique"]'::jsonb,3,'Safe handling prevents injury.','original'),
('116.62.c.3.B',3,'Which exercise technique is unsafe?','["Bouncing hard at the bottom of a deep stretch", "Warming up before heavy sets", "Keeping the spine neutral", "Slow controlled breathing during a lift"]'::jsonb,0,'Ballistic bouncing can strain muscles and joints.','original'),
('116.62.c.3.B',3,'Holding your breath and locking the knees during a heavy lift can be harmful because it can do what?','["Improve circulation", "Raise blood pressure and strain joints", "Strengthen bones instantly", "Prevent soreness"]'::jsonb,1,'Breath-holding and locked joints are risky.','original'),
('116.62.c.3.C',3,'On a hot, humid afternoon a runner sweats heavily. What is the best way to protect her?','["Wear extra layers", "Avoid water", "Drink fluids before, during and after exercise", "Run harder to finish sooner"]'::jsonb,2,'Hydration offsets fluid lost to sweat.','original'),
('116.62.c.3.C',3,'Which sign suggests a person may be becoming dehydrated during exercise?','["Feeling cool", "Steady energy", "Clear urine", "Dizziness, dark urine and a dry mouth"]'::jsonb,3,'Dehydration produces these signs.','original'),
('116.62.c.3.D',3,'Wellness includes more than the absence of disease. How does physical fitness relate to wellness?','["Fitness supports physical, mental and social wellness", "Fitness harms wellness", "Fitness has no effect", "Wellness only means diet"]'::jsonb,0,'Fitness is one part of overall wellness.','original'),
('116.62.c.3.D',3,'A student who exercises regularly sleeps better and copes with stress more easily. This shows fitness contributes to what?','["Only muscle size", "Overall wellness", "Only speed", "Only flexibility"]'::jsonb,1,'Fitness benefits several areas of wellness.','original'),
('116.62.c.3.E',2,'Which activity develops health-related fitness?','["Sitting during class", "Eating a snack", "Brisk swimming laps for 20 minutes", "Watching a video"]'::jsonb,2,'Sustained swimming builds cardiorespiratory endurance.','original'),
('116.62.c.3.E',2,'Which activity mainly develops muscular strength?','["Standing still", "Slow walking", "Stretching only", "Weight training with progressive resistance"]'::jsonb,3,'Resistance training builds strength.','original'),
('116.62.c.3.F',3,'To improve cardiorespiratory endurance, a person should train using which FITT idea?','["Sustained activity at a raised heart rate several days a week", "Resting every day", "Only lifting max weights", "One slow stretch a month"]'::jsonb,0,'Endurance improves with regular sustained aerobic work.','original'),
('116.62.c.3.F',3,'To build muscular endurance, a good plan uses what?','["No resistance", "Lighter loads with higher repetitions", "One max rep a month", "Only static holds of one second"]'::jsonb,1,'High reps with lighter loads build endurance.','original'),
('116.62.c.3.G',3,'Which pair includes one aerobic and one anaerobic activity?','["Swimming and rowing", "Stretching and yoga", "Distance cycling and heavy weightlifting", "Walking and jogging"]'::jsonb,2,'Cycling is aerobic and heavy lifting is anaerobic.','original'),
('116.62.c.3.G',3,'A 100-meter sprint relies mostly on what kind of energy system?','["Aerobic only", "Fat only", "No energy", "Anaerobic"]'::jsonb,3,'Short bursts of maximum effort are anaerobic.','original'),
('116.62.c.3.H',3,'A student uses a fitness watch to check her heart rate zones while running. What is this technology used for?','["Monitoring intensity to improve training", "Predicting the weather", "Replacing exercise", "Measuring height"]'::jsonb,0,'Heart-rate tracking helps guide intensity.','original'),
('116.62.c.3.H',3,'Which technology tool best helps count steps across a week?','["A stopwatch", "A pedometer or activity tracker", "A tape measure", "A scale"]'::jsonb,1,'Pedometers and trackers count steps.','original'),
('116.62.c.3.I',3,'A personal fitness plan should include which parts?','["No schedule", "A single exercise", "Goals, activities for each fitness component, and a way to track progress", "Only a favorite song"]'::jsonb,2,'A plan sets goals, activities and tracking.','original'),
('116.62.c.3.I',3,'Which is a SMART goal for a fitness program?','["Be better", "Get fit someday", "Exercise more maybe", "Run a mile in under 10 minutes by the end of 8 weeks"]'::jsonb,3,'SMART goals are specific, measurable and time-bound.','original'),
('116.62.c.3.J',3,'Agility, balance, coordination, power, reaction time and speed are examples of what?','["Skill-related components of fitness", "Types of injury", "Health-related components", "Types of food"]'::jsonb,0,'These are the skill-related components.','original'),
('116.62.c.3.J',3,'A shuttle run is commonly used to measure which skill-related component?','["Flexibility", "Agility", "Muscular endurance", "Body composition"]'::jsonb,1,'Shuttle runs test quick changes of direction.','original'),
('116.62.c.3.K',3,'A sit-and-reach test measures which health-related component?','["Power", "Cardiorespiratory endurance", "Flexibility", "Speed"]'::jsonb,2,'Sit-and-reach measures flexibility of the hamstrings and back.','original'),
('116.62.c.3.K',3,'A timed one-mile run is used to evaluate what?','["Balance", "Flexibility", "Reaction time", "Cardiorespiratory endurance"]'::jsonb,3,'Distance runs test aerobic capacity.','original'),
('116.62.c.4.A',3,'Regular physical activity is related to emotional health because it can do what?','["Reduce stress and improve mood", "Remove all sleep", "Cause isolation", "Increase every worry"]'::jsonb,0,'Exercise supports mood and lowers stress.','original'),
('116.62.c.4.A',3,'Playing on a team can improve social health by doing what?','["Ending trust", "Building cooperation and friendships", "Removing communication", "Encouraging isolation"]'::jsonb,1,'Team activity builds social skills.','original'),
('116.62.c.4.B',3,'A student who failed to run a mile in 12 minutes improves to 10 minutes after weeks of training. This shows that what?','["Practice is pointless", "Skill is fixed", "Improvement is possible with appropriate practice", "Only genetics matter"]'::jsonb,2,'Practice produces improvement.','original'),
('116.62.c.4.B',3,'Which statement shows a growth mindset about fitness?','["I never improve", "Training is useless", "I was born weak and always will be", "I can get stronger if I keep training consistently"]'::jsonb,3,'A growth mindset values effort.','original'),
('116.62.c.4.C',3,'A teammate misses the winning shot. Which is the best response?','["Encourage him and focus on learning from the play", "Mock him", "Leave the team", "Blame him"]'::jsonb,0,'Supportive responses handle failure well.','original'),
('116.62.c.4.C',3,'A conflict starts over a rule during a game. Which action resolves it best?','["Yell at the group", "Calmly discuss the rule and agree on a solution", "Ignore the rule", "Quit"]'::jsonb,1,'Calm communication resolves conflict.','original'),
('116.62.c.4.D',3,'A student wins a match and a rival loses. Which behavior shows good sportsmanship?','["Bragging loudly", "Ignoring the rival", "Shaking hands and acknowledging the opponent''s effort", "Making excuses"]'::jsonb,2,'Respect is shown in success and defeat.','original'),
('116.62.c.4.D',3,'Accepting a performance limitation, such as a slower time, means doing what?','["Cheating to hide it", "Giving up forever", "Blaming a teammate", "Working on it respectfully without putting yourself or others down"]'::jsonb,3,'Healthy acceptance is paired with effort.','original'),
('116.62.c.4.E',3,'Spending several hours on screens instead of moving can affect social and emotional health by doing what?','["Reducing activity and face-to-face connection", "Increasing fitness automatically", "Always improving mood", "Replacing sleep needs"]'::jsonb,0,'Excess screen time can reduce activity and connection.','original'),
('116.62.c.4.E',3,'Using a fitness app to share goals with friends can have what positive effect?','["It always lowers stress", "It can increase motivation and support", "It replaces exercise", "It prevents all injuries"]'::jsonb,1,'Social features can motivate.','original'),
('116.62.c.5.A',3,'Why is sleep important for an athlete?','["It reduces strength", "It is unrelated to training", "It allows the body to recover and supports performance", "It slows learning"]'::jsonb,2,'Recovery happens during sleep.','original'),
('116.62.c.5.A',3,'A student sleeping five hours a night before a meet will most likely experience what?','["Better reactions", "More energy for all events", "Faster recovery", "Slower reaction time and lower performance"]'::jsonb,3,'Sleep loss hurts performance.','original'),
('116.62.c.5.B',3,'Which statement is a myth about physical activity?','["Doing thousands of crunches burns the fat from your stomach only", "Warm-ups help prevent injury", "Exercise raises heart rate", "Muscles need rest"]'::jsonb,0,'Spot reduction is a myth.','original'),
('116.62.c.5.B',3,'Which is a nutrition myth?','["Protein helps muscle repair", "Skipping meals is a healthy way to lose weight fast", "Water supports exercise", "Whole grains give energy"]'::jsonb,1,'Skipping meals is not a healthy strategy.','original'),
('116.62.c.5.C',3,'Eating a balanced meal with carbohydrates before long exercise helps because it does what?','["Removes the need for water", "Replaces warm-up", "Provides energy for the workout", "Prevents all fatigue"]'::jsonb,2,'Carbohydrates fuel exercise.','original'),
('116.62.c.5.C',3,'After a hard workout, a snack with protein and carbohydrates helps by doing what?','["Reducing recovery", "Preventing sleep", "Causing dehydration", "Supporting muscle repair and restoring energy"]'::jsonb,3,'Protein and carbs aid recovery.','original'),
('116.62.c.5.D',3,'An athlete who trains hard every day with no rest days feels constantly tired and gets injured often. What is the likely cause?','["Over training", "Proper nutrition", "Good recovery", "Under training"]'::jsonb,0,'Too much training without recovery causes problems.','original'),
('116.62.c.5.D',3,'Which is a sign of over training?','["Steady improvement", "Persistent fatigue, declining performance and mood changes", "Better sleep", "Increased energy"]'::jsonb,1,'These are common signs of over training.','original'),
('116.62.c.5.E',3,'An ad promises that a pill will melt away fat without exercise. How should a smart consumer respond?','["Buy immediately", "Trust any celebrity", "Be skeptical and check the claim with a reliable source", "Share it with friends"]'::jsonb,2,'Marketing claims need evidence.','original'),
('116.62.c.5.E',3,'Which source is the most reliable for fitness advice?','["An anonymous ad", "A random comment", "A rumor", "A certified trainer or a medical professional"]'::jsonb,3,'Credentials indicate reliability.','original'),
('116.62.c.5.F',3,'Which combination best improves body composition?','["Regular exercise and balanced nutrition", "Sitting more", "Crash dieting only", "Skipping sleep"]'::jsonb,0,'Both exercise and nutrition affect body composition.','original'),
('116.62.c.5.F',3,'Body composition refers to the proportion of what in the body?','["Hair to skin", "Fat mass compared with lean mass such as muscle and bone", "Height to weight only", "Blood types"]'::jsonb,1,'It compares fat and lean tissue.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
